mapper.select:
SELECT vac.id, vac.mec_id, vac.campus_id, vac.student_id, stu.student_name, vac.start_time, vac.off_time, vac.apply_time, vac.dispose_time, vac.type, vac.leave_reason, vac.refuse_reason, vac.type, vac.call_record_id, vac.class_record_id, stu.student_name FROM bd_ask_leave vac LEFT JOIN bd_student stu ON vac.student_id = stu.id WHERE vac.is_delete = 0 and vac.mec_id = #{mecId} and vac.campus_id = #{campusId}
and student_name like CONCAT('%',#{studentName},'%')
and type = #{type}
ORDER BY vac.type ASC, vac.apply_time DESC
